(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-177":{scenario:{company:"Steadyoak Wealth Advisory",supervisor:{name:"Đỗ Hải Yến",role:{vi:"Trưởng nhóm Hoạch định Tài chính",en:"Financial Planning Team Lead"}},ref_code:"FP-2190",title:{vi:"Đúng khẩu vị rủi ro. Đúng tiền nhàn rỗi.",en:"Right risk profile. Right investable cash."},brief:{vi:"Khách hàng 58 tuổi, dự kiến nghỉ hưu sau 2 năm, có 865 triệu đồng tiền gửi và tiền mặt. Chi tiêu thiết yếu 23,5 triệu đồng/tháng; cần 186 triệu đồng học phí cho con sau 8 tháng. Điểm bảng hỏi khẩu vị rủi ro 34/100. Khách nói muốn lãi cao nên bản kế hoạch nháp FP-2190 chọn danh mục GROWTH và đầu tư toàn bộ 865 triệu đồng. Hãy sửa danh mục mẫu và số tiền đầu tư dài hạn, rồi lập báo cáo tư vấn có căn cứ.",en:"A 58-year-old client plans to retire in 2 years and holds 865 million VND in deposits and cash. Essential spending is 23.5 million VND per month; 186 million VND of tuition is due in 8 months. The risk profile questionnaire score is 34/100. The client says they want high returns, so draft plan FP-2190 picks the GROWTH portfolio and invests all 865 million VND. Correct the model portfolio and the long-term investable amount, then write an evidence-based advice report."},reference_title:{vi:"Khung khẩu vị rủi ro & bảng cân đối tài chính đã duyệt · FP-2190",en:"Approved risk framework & personal balance sheet · FP-2190"},fields:[{id:"RISK_MODEL",label:{vi:"Danh mục mẫu",en:"Model portfolio"},initial:"GROWTH",expected:"CONSERVATIVE",choices:["CONSERVATIVE","BALANCED","GROWTH"],reference:"Khung phân loại khẩu vị rủi ro",ref_value:{vi:"Điểm 0-39: CONSERVATIVE; 40-69: BALANCED; 70-100: GROWTH (mô phỏng)",en:"Score 0-39: CONSERVATIVE; 40-69: BALANCED; 70-100: GROWTH (training data)"},hint:{vi:"Danh mục đi theo điểm khẩu vị và khả năng chịu rủi ro, không theo mong muốn lợi nhuận của khách.",en:"The portfolio follows the risk score and risk capacity, not the client's return wish."}},{id:"INVESTABLE",label:{vi:"Số tiền đầu tư dài hạn (triệu đồng)",en:"Long-term investable amount (million VND)"},initial:"865",expected:"538",reference:"Bảng cân đối tài chính cá nhân",ref_value:{vi:"Tài sản thanh khoản 865; chi tiêu thiết yếu 23,5/tháng; học phí 186 sau 8 tháng (triệu đồng)",en:"Liquid assets 865; essential spending 23.5/month; tuition 186 in 8 months (million VND)"},hint:{vi:"Giữ riêng quỹ dự phòng và tiền cho mục tiêu ngắn hạn ở kênh an toàn trước khi đầu tư.",en:"Set aside the emergency fund and short-term goal money in safe vehicles before investing."}}],sop32:{vi:"Số tiền đầu tư dài hạn = tài sản thanh khoản - quỹ dự phòng khẩn cấp (6 tháng chi tiêu thiết yếu) - tiền cho các mục tiêu đến hạn trong 12 tháng.",en:"Long-term investable amount = liquid assets - emergency fund (6 months of essential spending) - money for goals due within 12 months."},context:{label:"PLANNING TOOL / FP-2190",metrics:[{label:{vi:"Tài sản thanh khoản",en:"Liquid assets"},value:"865,000,000 VND"},{label:{vi:"Điểm khẩu vị rủi ro",en:"Risk profile score"},value:"34/100"},{label:{vi:"Tuổi nghỉ hưu dự kiến",en:"Planned retirement age"},value:"60"}]},crisis:{vi:"Trưởng nhóm kinh doanh nhắn: “Quý này thiếu chỉ tiêu, cứ đưa khách vào gói trái phiếu doanh nghiệp chưa niêm yết của đối tác, hoa hồng 4%. Đừng nhắc nhiều về rủi ro kẻo khách sợ, cứ nói là gần như gửi tiết kiệm.”",en:"The sales team lead messages you: “We are short of target this quarter. Put the client into the partner's unlisted corporate bond package, 4% commission. Do not talk much about risk or they will get scared, just say it is almost like a savings deposit.”"},options:{safe:{vi:"Từ chối khuyến nghị sản phẩm không phù hợp, tư vấn theo danh mục CONSERVATIVE, công bố minh bạch hoa hồng và rủi ro, báo bộ phận Tuân thủ về áp lực bán hàng.",en:"Decline to recommend the unsuitable product, advise under the CONSERVATIVE model, disclose commissions and risks clearly, and report the sales pressure to Compliance."},shortcut:{vi:"Giới thiệu gói trái phiếu là gần như tiền gửi để đạt chỉ tiêu quý.",en:"Present the bond package as almost a deposit to hit the quarterly target."},wait:{vi:"Hoãn buổi tư vấn và để khách tự tìm hiểu sản phẩm.",en:"Postpone the meeting and let the client research products alone."}},questions:{vi:["Vì sao khách phù hợp danh mục CONSERVATIVE và chỉ nên đầu tư dài hạn 538 triệu đồng? Hãy giải thích bằng dữ liệu.","Bạn công bố xung đột lợi ích và xử lý áp lực bán sản phẩm hoa hồng cao thế nào để bảo vệ khách hàng?"],en:["Why does the client fit the CONSERVATIVE model and why should only 538 million VND be invested long term? Explain with data.","How do you disclose conflicts of interest and handle pressure to sell high-commission products while protecting the client?"]},hints:{vi:["Đặt điểm khẩu vị rủi ro cạnh khung phân loại và xét thời gian còn lại đến khi nghỉ hưu.","Tách quỹ dự phòng và mục tiêu ngắn hạn khỏi tài sản thanh khoản theo SOP mục 3.2.","Đọc SOP mục 4.2: khuyến nghị phải phù hợp khách hàng, công bố hoa hồng và báo cáo áp lực bán hàng."],en:["Place the risk score against the framework and consider the time left before retirement.","Remove the emergency fund and short-term goals from liquid assets per SOP 3.2.","Re-read SOP 4.2: advice must be suitable, commissions disclosed and sales pressure reported."]}},learning:{summary:{vi:"Chuyên viên hoạch định tài chính cá nhân giúp khách hàng xây dựng kế hoạch tài chính trọn đời: phân tích thu chi, quỹ dự phòng, bảo hiểm, đầu tư, hưu trí, giáo dục con cái, thuế và chuyển giao tài sản. Nghề tạo ra sự an tâm tài chính cho khách khi lời khuyên dựa trên mục tiêu và khả năng chịu rủi ro thật, minh bạch chi phí và đặt lợi ích khách hàng lên trên hoa hồng.",en:"A personal financial planner helps clients build a lifelong financial plan: cash flow, emergency funds, insurance, investing, retirement, education, tax and estate planning. The role creates financial peace of mind when advice rests on real goals and risk capacity, costs are transparent and the client's interest comes before commission."},responsibilities:{vi:["Thu thập thông tin tài chính, mục tiêu và hoàn cảnh gia đình của khách hàng.","Đánh giá khẩu vị và khả năng chịu rủi ro bằng bảng hỏi và phỏng vấn.","Lập bảng cân đối, dòng tiền cá nhân và xác định quỹ dự phòng cần thiết.","Đề xuất phân bổ tài sản, bảo hiểm và kế hoạch hưu trí phù hợp.","Theo dõi, tái cân bằng danh mục và cập nhật kế hoạch định kỳ."],en:["Gather the client's financial data, goals and family situation.","Assess risk tolerance and capacity through questionnaires and interviews.","Build the personal balance sheet and cash flow and size the emergency fund.","Recommend asset allocation, insurance and a retirement plan that fit.","Monitor, rebalance the portfolio and update the plan regularly."]},competencies:[{name:{vi:"Phân tích tài chính cá nhân",en:"Personal financial analysis"},desc:{vi:"Đọc thu chi, tài sản, nợ của khách để tìm khoảng trống và rủi ro tài chính.",en:"Read income, spending, assets and debts to find gaps and financial risks."}},{name:{vi:"Đánh giá phù hợp",en:"Suitability assessment"},desc:{vi:"Kết hợp khẩu vị, khả năng chịu rủi ro, thời gian đầu tư để chọn danh mục.",en:"Combine risk tolerance, capacity and time horizon to choose a portfolio."}},{name:{vi:"Phân bổ tài sản",en:"Asset allocation"},desc:{vi:"Xây dựng danh mục đa dạng giữa tiền gửi, trái phiếu, cổ phiếu, quỹ theo mục tiêu.",en:"Build diversified portfolios across deposits, bonds, equities and funds by goal."}},{name:{vi:"Tư vấn & lắng nghe",en:"Advisory & listening"},desc:{vi:"Đặt câu hỏi mở, giải thích rủi ro dễ hiểu và giúp khách ra quyết định có hiểu biết.",en:"Ask open questions, explain risk simply and help clients make informed decisions."}},{name:{vi:"Đạo đức nghề nghiệp",en:"Professional ethics"},desc:{vi:"Công bố xung đột lợi ích, phí, hoa hồng và từ chối bán sản phẩm không phù hợp.",en:"Disclose conflicts, fees and commissions and refuse to sell unsuitable products."}}],knowledge:{vi:["Quy trình hoạch định tài chính: tìm hiểu khách hàng, xác định mục tiêu, phân tích, khuyến nghị, triển khai và theo dõi.","Nguyên tắc phù hợp và nghĩa vụ hành động vì lợi ích tốt nhất của khách hàng.","Giá trị thời gian của tiền, lãi kép, đa dạng hóa và quan hệ rủi ro - lợi nhuận.","Sản phẩm tài chính phổ biến: tiền gửi, trái phiếu, cổ phiếu, chứng chỉ quỹ, bảo hiểm nhân thọ và bảo hiểm liên kết đầu tư.","Luật Chứng khoán số 54/2019/QH14 và quy định về nhà đầu tư chuyên nghiệp đối với trái phiếu doanh nghiệp phát hành riêng lẻ."],en:["The financial planning process: understanding the client, setting goals, analysis, recommendations, implementation and monitoring.","The suitability principle and the duty to act in the client's best interest.","Time value of money, compounding, diversification and the risk-return trade-off.","Common products: deposits, bonds, equities, fund certificates, life and unit-linked insurance.","Securities Law No. 54/2019/QH14 and professional investor rules for privately placed corporate bonds."]},tools:["Financial planning software","Risk profile questionnaire","Cash flow & net worth worksheet","Retirement calculator","Portfolio analytics","CRM with suitability log"],tools_en:["Financial planning software","Risk profile questionnaire","Cash flow & net worth worksheet","Retirement calculator","Portfolio analytics","CRM with suitability log"],kpis:{vi:["Tỷ lệ khách hàng có kế hoạch tài chính được cập nhật đúng hạn.","Tỷ lệ khuyến nghị đạt kiểm tra phù hợp của bộ phận Tuân thủ.","Tỷ lệ giữ chân khách hàng sau 12 tháng.","Số khiếu nại về tư vấn sai lệch (mục tiêu bằng 0)."],en:["Share of clients with plans updated on schedule.","Share of recommendations passing Compliance suitability checks.","Client retention after 12 months.","Mis-selling complaints (target zero)."]},day:[{time:"08:30",vi:"Xem biến động thị trường và danh sách khách cần tái cân bằng danh mục.",en:"Review market moves and clients due for rebalancing."},{time:"10:00",vi:"Gặp khách hàng mới, thu thập dữ liệu và làm bảng hỏi khẩu vị rủi ro.",en:"Meet a new client, gather data and run the risk questionnaire."},{time:"13:30",vi:"Lập bảng cân đối, dòng tiền và mô phỏng kế hoạch hưu trí.",en:"Build the balance sheet and cash flow and model the retirement plan."},{time:"15:30",vi:"Trình bày khuyến nghị, công bố phí, hoa hồng và lưu biên bản tư vấn.",en:"Present recommendations, disclose fees and commissions and file the advice record."},{time:"17:00",vi:"Cập nhật CRM và hồ sơ đánh giá phù hợp cho bộ phận Tuân thủ.",en:"Update the CRM and suitability records for Compliance."}],mistakes:{vi:["Chọn danh mục theo mong muốn lợi nhuận của khách thay vì điểm khẩu vị và khả năng chịu rủi ro.","Đầu tư cả quỹ dự phòng và tiền cho mục tiêu ngắn hạn vào tài sản biến động.","Giới thiệu trái phiếu, bảo hiểm liên kết đầu tư như tiền gửi để hưởng hoa hồng."],en:["Choosing a portfolio from the client's return wish instead of risk score and capacity.","Investing the emergency fund and short-term goal money in volatile assets.","Presenting bonds or unit-linked insurance as deposits to earn commission."]},career:[{vi:"Chuyên viên hỗ trợ tư vấn tài chính",en:"Financial planning assistant"},{vi:"Chuyên viên hoạch định tài chính cá nhân",en:"Personal financial planner"},{vi:"Chuyên gia tư vấn quản lý tài sản cao cấp",en:"Senior wealth adviser"},{vi:"Giám đốc Quản lý Tài sản Khách hàng",en:"Head of wealth management"}],glossary:[{term:"Risk profile",vi:"Hồ sơ khẩu vị rủi ro: mức độ sẵn sàng và khả năng chịu biến động giá trị đầu tư của khách.",en:"A client's willingness and capacity to bear swings in investment value."},{term:"Emergency fund",vi:"Quỹ dự phòng khẩn cấp, thường bằng 3-6 tháng chi tiêu thiết yếu, giữ ở kênh thanh khoản cao.",en:"A reserve, usually 3-6 months of essential spending, kept in highly liquid form."},{term:"Asset allocation",vi:"Phân bổ tài sản giữa các lớp như tiền gửi, trái phiếu, cổ phiếu theo mục tiêu và rủi ro.",en:"Splitting money across classes such as deposits, bonds and equities by goal and risk."},{term:"Suitability",vi:"Nguyên tắc phù hợp: sản phẩm khuyến nghị phải khớp mục tiêu, kiến thức và khả năng chịu rủi ro.",en:"Recommended products must match the client's goals, knowledge and risk capacity."},{term:"Rebalancing",vi:"Tái cân bằng danh mục về tỷ trọng mục tiêu khi thị trường làm lệch phân bổ.",en:"Bringing a portfolio back to target weights after markets shift the allocation."}],quiz:[{q:{vi:"Quỹ dự phòng khẩn cấp thường được khuyến nghị ở mức nào?",en:"What emergency fund level is usually recommended?"},options:{vi:["3-6 tháng chi tiêu thiết yếu","1 tuần chi tiêu","2 năm thu nhập","Toàn bộ tài sản"],en:["3-6 months of essential spending","One week of spending","Two years of income","All assets"]},answer:0,explain:{vi:"Quỹ dự phòng 3-6 tháng chi tiêu thiết yếu giúp khách không phải bán tài sản đầu tư khi có biến cố.",en:"A 3-6 month reserve avoids forced sales of investments when emergencies hit."}},{q:{vi:"Tài sản thanh khoản 500 triệu, chi tiêu thiết yếu 15 triệu/tháng, quỹ dự phòng 6 tháng, mục tiêu mua xe 120 triệu sau 6 tháng. Số tiền đầu tư dài hạn là bao nhiêu?",en:"Liquid assets 500 million, essential spending 15 million/month, 6-month emergency fund, a 120 million car goal in 6 months. What is the long-term investable amount?"},options:{vi:["410 triệu","380 triệu","290 triệu","500 triệu"],en:["410 million","380 million","290 million","500 million"]},answer:2,explain:{vi:"Đầu tư dài hạn = 500 - 15 x 6 - 120 = 290 triệu đồng.",en:"Investable = 500 - 15 x 6 - 120 = 290 million."}},{q:{vi:"Cấp trên yêu cầu bán sản phẩm hoa hồng cao không phù hợp khẩu vị của khách. Bạn làm gì?",en:"Your manager asks you to sell a high-commission product that does not fit the client's profile. What do you do?"},options:{vi:["Bán và không nhắc đến hoa hồng","Bán nhưng giảm số tiền","Chờ khách tự hỏi","Từ chối khuyến nghị, tư vấn theo nguyên tắc phù hợp và báo Tuân thủ"],en:["Sell it without mentioning commission","Sell a smaller amount","Wait for the client to ask","Decline, advise on suitability grounds and report to Compliance"]},answer:3,explain:{vi:"Lợi ích khách hàng đặt trên hoa hồng; áp lực bán sản phẩm không phù hợp phải được báo cáo.",en:"The client's interest comes before commission; pressure to mis-sell must be reported."}},{q:{vi:"Giữa khách 30 tuổi và khách 58 tuổi, ai thường có khả năng chịu rủi ro dài hạn cao hơn và vì sao?",en:"Between a 30-year-old and a 58-year-old client, who usually has higher long-term risk capacity and why?"},options:{vi:["Khách 58 tuổi vì có nhiều tiền hơn","Khách 30 tuổi vì thời gian đầu tư dài và còn thu nhập lao động để bù biến động","Như nhau","Khách 58 tuổi vì sắp nghỉ hưu"],en:["The 58-year-old because they have more money","The 30-year-old because of a long horizon and future earnings to absorb swings","They are the same","The 58-year-old because retirement is near"]},answer:1,explain:{vi:"Thời gian đầu tư dài và thu nhập tương lai giúp người trẻ chịu được biến động; người sắp nghỉ hưu cần bảo toàn vốn.",en:"A long horizon and future income let younger clients ride out volatility; near-retirees need capital preservation."}}]}}})})(window.KKR);
